ControlPropertyState.AutoRuleBindingString:
With(
    {s: lkTicketsTable.Selected},
    With(
        {
            cur: If(
                IsBlank(s.Title), 1,
                Switch(
                    Lower(Coalesce(s.RequestStatus, "submitted")),
                    "submitted", 2,
                    "in review", 2,
                    "approved", 3,
                    "in progress", 3,
                    "completed", 5,
                    "closed", 5,
                    2
                )
            )
        },
        ForAll(
            Table(
                {Step: 1, Name: If(IsBlank(s.Title), "You", Coalesce(s.RequesterName, "Requester")), Role: "Request submitted"},
                {Step: 2, Name: If(IsBlank(s.Title), lkApprover.Text, Coalesce(s.AuthorizedBy, lkApprover.Text)), Role: "Supervisor review"},
                {Step: 3, Name: "Locksmith", Role: "Work in progress"},
                {Step: 4, Name: "Done", Role: "Request completed"}
            ),
            {
                Step: Step,
                Name: Name,
                Role: Role,
                Status: If(Step < cur, "done", Step = cur, "current", "waiting"),
                IsFirst: Step = 1,
                IsLast: Step = 4
            }
        )
    )
)
